import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import ReactDOM from 'react-dom';
import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { theme, getSetting, putSetting } from '@atlantis/shared';
import { createT, localizedTimeAgo } from '@atlantis/i18n';
import type { Locale, TFunction } from '@atlantis/i18n';
import SHELL_KEYS from './translations';

interface RssItem {
  title: string;
  link: string;
  pubDate: string;
}

interface RssCacheEntry {
  data: { items: RssItem[] };
  cachedAt: number;
}

interface FeedSource {
  id: 'news-pt' | 'news-world';
  cacheKey: string;
  badgeKey: string; // translation key for the source badge
  badgeColor: string;
}

const SOURCES: FeedSource[] = [
  {
    id: 'news-pt',
    cacheKey: 'widget-cache:news-portugal',
    badgeKey: 'notifications.source.newsPt',
    badgeColor: '#2da44e',
  },
  {
    id: 'news-world',
    cacheKey: 'widget-cache:news-world',
    badgeKey: 'notifications.source.newsWorld',
    badgeColor: '#cc0000',
  },
];

const LAST_SEEN_KEY = 'notifications:lastSeenAt';
const POLL_MS = 60_000;

interface NotifItem extends RssItem {
  source: FeedSource;
  ts: number;
}

async function readNewItems(lastSeenAt: number): Promise<NotifItem[]> {
  const collected: NotifItem[] = [];
  await Promise.all(
    SOURCES.map(async (source) => {
      const raw = await getSetting(source.cacheKey);
      if (!raw) return;
      let parsed: RssCacheEntry;
      try {
        parsed = JSON.parse(raw);
      } catch {
        return;
      }
      for (const it of parsed.data?.items ?? []) {
        const ts = Date.parse(it.pubDate);
        if (Number.isNaN(ts)) continue;
        if (ts <= lastSeenAt) continue;
        collected.push({ ...it, source, ts });
      }
    }),
  );
  collected.sort((a, b) => b.ts - a.ts);
  return collected.slice(0, 30);
}

interface NotificationBellState {
  count: number;
  open: boolean;
  toggle: () => void;
  close: () => void;
  items: NotifItem[];
  markAllRead: () => Promise<void>;
}

/** Hook — owns lastSeen state + polls caches for fresh items. */
export function useNotificationBell(): NotificationBellState {
  const [items, setItems] = useState<NotifItem[]>([]);
  const [open, setOpen] = useState(false);
  const lastSeenRef = useRef<number>(0);

  const refresh = useCallback(async () => {
    const next = await readNewItems(lastSeenRef.current);
    setItems(next);
  }, []);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const raw = await getSetting(LAST_SEEN_KEY);
      lastSeenRef.current = raw ? Number(raw) || 0 : 0;
      if (!cancelled) refresh();
    })();
    const id = window.setInterval(refresh, POLL_MS);
    const onFocus = () => refresh();
    window.addEventListener('focus', onFocus);
    return () => {
      cancelled = true;
      window.clearInterval(id);
      window.removeEventListener('focus', onFocus);
    };
  }, [refresh]);

  const toggle = useCallback(() => setOpen((v) => !v), []);
  const close = useCallback(() => setOpen(false), []);

  const markAllRead = useCallback(async () => {
    const now = Date.now();
    lastSeenRef.current = now;
    await putSetting(LAST_SEEN_KEY, String(now));
    setItems([]);
  }, []);

  return {
    count: items.length,
    open,
    toggle,
    close,
    items,
    markAllRead,
  };
}

