/**
 * Maps `apps.config.yml` → 5 named Atlantis suites used by the header
 * `SuitesMenu`. Developer Toolkit is intentionally excluded (devtools live
 * in their own home-screen section).
 *
 * User rules (2026-04-18):
 *   - Clicking a suite row navigates straight to the suite area. The
 *     "suite area" is the home screen's `activeSuite` filter; we jump via
 *     `#/home?suite=<id>` and let `HomeScreen.tsx` pick up the param.
 *   - Games is the one exception: clicking it expands a child list of
 *     individual games (keeps parent context). Reuse `GAMES_CHILDREN` for
 *     that list + for the command palette + for any future widget that
 *     wants a "games I can launch now" surface.
 */

import { useMemo } from 'react';
import { theme } from '@atlantis/shared';
import type { SuiteEntry, IconName } from '@atlantis/ui';
import type { TFunction } from '@atlantis/i18n';
import type { AppConfig } from './apps.config';

interface SuiteSpec {
  id: 'lab' | 'vida' | 'learn' | 'games' | 'ent';
  /** Matches `suite:` value in `apps.config.yml`. */
  yamlSuite: string;
  color: string;
  icon: IconName;
  nameKey: string;
  subKey: string;
}

const SUITE_SPECS: SuiteSpec[] = [
  { id: 'lab',   yamlSuite: 'AI Lab',         color: theme.suites.lab,   icon: 'beaker',     nameKey: 'suites.lab.name',   subKey: 'suites.lab.sub' },
  { id: 'vida',  yamlSuite: 'Life Dashboard', color: theme.suites.vida,  icon: 'heart',      nameKey: 'suites.vida.name',  subKey: 'suites.vida.sub' },
  { id: 'learn', yamlSuite: 'Learning Hub',   color: theme.suites.learn, icon: 'graduation', nameKey: 'suites.learn.name', subKey: 'suites.learn.sub' },
  { id: 'games', yamlSuite: 'Game Room',      color: theme.suites.games, icon: 'gamepad',    nameKey: 'suites.games.name', subKey: 'suites.games.sub' },
  { id: 'ent',   yamlSuite: 'Entertainment',  color: theme.suites.ent,   icon: 'film',       nameKey: 'suites.ent.name',   subKey: 'suites.ent.sub' },
];

export interface GameEntry {
  id: string;
  hash: string;
  glyph: string;
  labelKey: string;
}

/** Mirror of `WidgetGrid.tsx` → `QUICK_LAUNCH.games`. Keep in sync. */
export const GAMES_CHILDREN: GameEntry[] = [
  { id: 'tictactoe',  hash: '#/tictactoe',  glyph: '⭕', labelKey: 'quickLaunch.tictactoe' },
  { id: 'memory',     hash: '#/memory',     glyph: '🧠', labelKey: 'quickLaunch.memory' },
  { id: 'pixelboard', hash: '#/pixelboard', glyph: '🎨', labelKey: 'quickLaunch.pixelboard' },
  { id: 'familyquiz', hash: '#/familyquiz', glyph: '❓', labelKey: 'quickLaunch.familyquiz' },
  { id: 'spotit',     hash: '#/spotit',     glyph: '👀', labelKey: 'quickLaunch.spotit' },
  { id: 'stopgame',   hash: '#/stopgame',   glyph: '✋', labelKey: 'quickLaunch.stopgame' },
];

/**
 * Build the `SuiteEntry[]` for `<HeaderRight suites={…} />`.
 *
 * The "suite area" navigation target is today the home-screen filtered
 * view. We wire that via `onHomeSuite(id)` — caller-supplied so the shell
 * can update hash + reset any conflicting state in one place.
 */
export function useSuites(
  apps: AppConfig[],
  t: TFunction,
  onHomeSuite: (suiteId: SuiteSpec['id']) => void,
  navigate: (hash: string) => void,
): SuiteEntry[] {
  return useMemo(() => {
    return SUITE_SPECS.map<SuiteEntry>((spec) => {
      const inSuite = apps.filter((a) => a.suite === spec.yamlSuite);
      const isGames = spec.id === 'games';

      const children = isGames
        ? GAMES_CHILDREN.map((g) => ({
            id: g.id,
            name: t(g.labelKey),
            glyph: g.glyph,
            onClick: () => navigate(g.hash),
          }))
        : undefined;

      return {
        id: spec.id,
        name: t(spec.nameKey),
        subtitle: t(spec.subKey),
        color: spec.color,
        icon: spec.icon,
        count: isGames ? GAMES_CHILDREN.length : inSuite.length,
        // Games uses inline children → no top-level click. Other suites
        // jump to the home suite-area view.
        onClick: isGames ? undefined : () => onHomeSuite(spec.id),
        children,
      };
    });
  }, [apps, t, onHomeSuite, navigate]);
}
