// ── Public types ──────────────────────────────────────────────────────────

export interface AppEntry {
  id: string;
  label: string;
  hash: string;
  icon: string;
  description: string;
  color: string;
  category: string;
}

export interface PaletteSuite {
  id: string;
  name: string;
  sub?: string;
  color: string;
  iconName: IconName;
  /** Displayed on the right as a shortcut chip (e.g. `['G','L']`). */
  shortcut?: string[];
  onConfirm: () => void;
}

export interface PaletteGame {
  id: string;
  name: string;
  glyph: string;
  hash: string;
}

export interface PaletteAction {
  id: string;
  label: string;
  meta?: string;
  iconName: IconName;
  color?: string;
  shortcut?: string[];
  onClick: () => void;
}

interface Props {
  apps: AppEntry[];
  recentIds: string[];
  suites?: PaletteSuite[];
  games?: PaletteGame[];
  actions?: PaletteAction[];
  hasAsk?: boolean;
  groqKey?: string;
  locale: Locale;
  onNavigate: (hash: string) => void;
  onClose: () => void;
}

// ── Internal model ────────────────────────────────────────────────────────

type Scope = 'all' | 'jump' | 'actions' | 'ask' | 'recent';

interface CommandItem {
  id: string;
  kind: 'app' | 'suite' | 'game' | 'action' | 'suggest';
  label: string;
  meta?: string;
  isRecent?: boolean;
  appIcon?: { emoji: string; color: string };
  glyphIcon?: { iconName: IconName; color: string };
  gameGlyph?: string;
  shortcut?: string[];
  onConfirm: () => void;
}

type ListItem =
  | { kind: 'header'; label: string; key: string; count: number }
  | { kind: 'item'; item: CommandItem };

// ── Chat turn types ───────────────────────────────────────────────────────

interface ChatTurn {
  id: string;
  question: string;
  /** undefined = still loading */
  answer?: string;
  error?: string;
}

