// ── Helpers ──────────────────────────────────────────────────────────────

function matches(item: { label: string; meta?: string }, q: string): boolean {
  if (!q) return true;
  const needle = q.toLowerCase();
  return (
    item.label.toLowerCase().includes(needle) ||
    (item.meta?.toLowerCase().includes(needle) ?? false)
  );
}

// ── Component ────────────────────────────────────────────────────────────

export function CommandPalette({
  apps,
  recentIds,
  suites = [],
  games = [],
  actions = [],
  hasAsk = false,
  groqKey,
  locale,
  onNavigate,
  onClose,
}: Props) {
  const t: TFunction = useMemo(() => createT(locale, SHELL_KEYS), [locale]);
  const [query, setQuery] = useState('');
  const [scope, setScope] = useState<Scope>('all');
  const [selectedIndex, setSelectedIndex] = useState(0);
  /** In-session conversation history — clears when the palette is closed/reopened. */
  const [chatTurns, setChatTurns] = useState<ChatTurn[]>([]);
  const [isThinking, setIsThinking] = useState(false);
  /** Ref copy of chatTurns for use inside async callbacks without stale closures. */
  const chatTurnsRef = useRef<ChatTurn[]>([]);

  const inputRef = useRef<HTMLInputElement | null>(null);
  const listRef = useRef<HTMLDivElement | null>(null);
  const chatEndRef = useRef<HTMLDivElement | null>(null);
  const askAbortRef = useRef<AbortController | null>(null);

  useEffect(() => {
    inputRef.current?.focus();
    return () => { askAbortRef.current?.abort(); };
  }, []);

  // Keep ref in sync with state.
  useEffect(() => { chatTurnsRef.current = chatTurns; }, [chatTurns]);

  // Scroll to bottom of chat on new turns.
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatTurns, isThinking]);

  // Build a single CommandItem[] from every source.
  const allItems = useMemo<CommandItem[]>(() => {
    const recentSet = new Set(recentIds);

    const appItems: CommandItem[] = apps.map((a) => ({
      id: `app:${a.id}`,
      kind: 'app',
      label: a.label,
      meta: a.description,
      isRecent: recentSet.has(a.id),
      appIcon: { emoji: a.icon, color: a.color },
      onConfirm: () => { onNavigate(a.hash); onClose(); },
    }));

    const suiteItems: CommandItem[] = suites.map((s) => ({
      id: `suite:${s.id}`,
      kind: 'suite',
      label: s.name,
      meta: s.sub,
      glyphIcon: { iconName: s.iconName, color: s.color },
      shortcut: s.shortcut,
      onConfirm: () => { s.onConfirm(); onClose(); },
    }));

    const gameItems: CommandItem[] = games.map((g) => ({
      id: `game:${g.id}`,
      kind: 'game',
      label: g.name,
      meta: t('palette.meta.game'),
      gameGlyph: g.glyph,
      onConfirm: () => { onNavigate(g.hash); onClose(); },
    }));

    const actionItems: CommandItem[] = actions.map((a) => ({
      id: `action:${a.id}`,
      kind: 'action',
      label: a.label,
      meta: a.meta,
      glyphIcon: {
        iconName: a.iconName,
        color: a.color ?? theme.colors.accent,
      },
      shortcut: a.shortcut,
      onConfirm: () => { a.onClick(); onClose(); },
    }));

    return [...suiteItems, ...appItems, ...gameItems, ...actionItems];
  }, [apps, suites, games, actions, recentIds, onNavigate, onClose, t]);

  // Group by the active scope.
  const grouped = useMemo<ListItem[]>(() => {
    if (scope === 'ask') return [];


    const filtered = allItems.filter((it) => matches(it, query));
    const sections: ListItem[] = [];
    const push = (key: string, labelKey: string, items: CommandItem[]) => {
      if (items.length === 0) return;
      sections.push({ kind: 'header', label: t(labelKey), key, count: items.length });
      for (const it of items) sections.push({ kind: 'item', item: it });
    };

    if (scope === 'recent') {
      const recents = allItems
        .filter((it) => it.kind === 'app' && it.isRecent && matches(it, query))
        .sort((a, b) => {
          const ai = recentIds.indexOf(a.id.slice('app:'.length));
          const bi = recentIds.indexOf(b.id.slice('app:'.length));
          return ai - bi;
        });
      push('recent', 'palette.recent', recents);
      return sections;
    }

    if (scope === 'jump') {
      push('suites', 'palette.section.suites', filtered.filter((it) => it.kind === 'suite'));
      push('apps',   'palette.section.apps',   filtered.filter((it) => it.kind === 'app'));
      push('games',  'palette.section.games',  filtered.filter((it) => it.kind === 'game'));
      return sections;
    }

    if (scope === 'actions') {
      push('actions', 'palette.section.actions', filtered.filter((it) => it.kind === 'action'));
      return sections;
    }

    // scope === 'all' — mirror the screenshot: SALTAR / AÇÕES / PERGUNTAR
    push('jump',    'palette.section.jump',    filtered.filter((it) => it.kind === 'suite' || it.kind === 'app' || it.kind === 'game'));
    push('actions', 'palette.section.actions', filtered.filter((it) => it.kind === 'action'));

    // Ask suggestions (only in the `all` view and only if Ask is enabled).
    if (hasAsk && groqKey) {
      const suggestItems: CommandItem[] = SUGGESTIONS_KEYS.map((k, i) => ({
        id: `suggest:${i}`,
        kind: 'suggest',
        label: t(k),
        meta: t('palette.ask.suggestMeta'),
        shortcut: ['↵'],
        onConfirm: () => {
          setScope('ask');
          // runAsk clears the query after submitting.
          setTimeout(() => { void runAsk(t(k)); }, 0);
        },
      }));
      push('ask', 'palette.section.ask', suggestItems);
    }

    return sections;
  }, [scope, query, allItems, recentIds, t, hasAsk, groqKey]);

  const selectableItems = useMemo(
    () => grouped.filter((g): g is { kind: 'item'; item: CommandItem } => g.kind === 'item'),
    [grouped],
  );

  useEffect(() => { setSelectedIndex(0); }, [scope, query]);

  useEffect(() => {
    const list = listRef.current;
    if (!list) return;
    const rows = list.querySelectorAll<HTMLElement>('[data-selectable]');
    rows[selectedIndex]?.scrollIntoView({ block: 'nearest' });
  }, [selectedIndex]);

  // ── Ask flow ──────────────────────────────────────────────────────────

  const runAsk = useCallback(async (question: string) => {
    if (!groqKey || !question.trim()) return;
    const q = question.trim();

    // Build the turn id and add a loading turn.
    const turnId = `turn-${Date.now()}`;
    setChatTurns((prev) => [...prev, { id: turnId, question: q }]);
    setIsThinking(true);
    setQuery('');

    // Build message history from previous completed turns (via ref to avoid stale closure).
    const historyMessages: GroqMessage[] = [];
    for (const turn of chatTurnsRef.current) {
      if (turn.answer) {
        historyMessages.push({ role: 'user', content: turn.question });
        historyMessages.push({ role: 'assistant', content: turn.answer });
      }
    }

    askAbortRef.current?.abort();
    const ac = new AbortController();
    askAbortRef.current = ac;

    try {
      const answer = await askGroq(q, {
        key: groqKey,
        locale: locale === 'pt' ? 'pt' : 'en',
        signal: ac.signal,
        history: historyMessages,
      });
      if (!ac.signal.aborted) {
        setChatTurns((prev) =>
          prev.map((t) => (t.id === turnId ? { ...t, answer } : t)),
        );
      }
    } catch (err) {
      if (ac.signal.aborted) return;
      const msg = err instanceof Error ? err.message : String(err);
      setChatTurns((prev) =>
        prev.map((t) => (t.id === turnId ? { ...t, error: msg } : t)),
      );
    } finally {
      if (!ac.signal.aborted) setIsThinking(false);
    }
  }, [groqKey, locale]);

  // ── Keyboard ──────────────────────────────────────────────────────────

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === 'Escape') {
        // If in ask scope with text typed, clear input first.
        if (scope === 'ask' && query.trim()) {
          setQuery('');
          return;
        }
        // If in ask scope with history, abort any in-flight request.
        if (scope === 'ask' && chatTurns.length > 0) {
          askAbortRef.current?.abort();
          setIsThinking(false);
          setChatTurns([]);
          return;
        }
        onClose();
        return;
      }
      if (scope === 'ask') {
        if (e.key === 'Enter' && query.trim()) {
          e.preventDefault();
          runAsk(query.trim());
        }
        return;
      }
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSelectedIndex((i) => Math.min(i + 1, selectableItems.length - 1));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSelectedIndex((i) => Math.max(i - 1, 0));
      } else if (e.key === 'Enter') {
        const sel = selectableItems[selectedIndex];
        if (sel) sel.item.onConfirm();
      }
    },
    [scope, query, chatTurns.length, selectableItems, selectedIndex, onClose, runAsk],
  );

  const handleBackdropClick = useCallback(
    (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) onClose();
    },
    [onClose],
  );

  const placeholder = scope === 'ask'
    ? (chatTurns.length > 0 ? t('palette.ask.followUp') : t('palette.ask.placeholder'))
    : t('palette.placeholder');

  let counter = -1;

  return ReactDOM.createPortal(
    <Backdrop onClick={handleBackdropClick}>
      <Panel onClick={(e) => e.stopPropagation()}>
        <Header>
          <SparkleCell active={scope === 'ask'}>
            <Icon name={scope === 'ask' ? 'sparkle' : 'search'} size={20} aria-hidden="true" />
          </SparkleCell>
          <Input
            ref={inputRef}
            placeholder={placeholder}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            aria-label={t('palette.search')}
          />
          <EscBadge>esc</EscBadge>
        </Header>

        <Tabs role="tablist">
          <Tab role="tab" active={scope === 'all'}     onClick={() => setScope('all')}>{t('palette.scope.all')}</Tab>
          <Tab role="tab" active={scope === 'jump'}    onClick={() => setScope('jump')}>{t('palette.scope.jump')}</Tab>
          <Tab role="tab" active={scope === 'actions'} onClick={() => setScope('actions')}>{t('palette.scope.actions')}</Tab>
          {hasAsk && groqKey && (
            <Tab role="tab" active={scope === 'ask'} highlight onClick={() => setScope('ask')}>
              {t('palette.scope.ask')}
            </Tab>
          )}
          <Tab role="tab" active={scope === 'recent'}  onClick={() => setScope('recent')}>{t('palette.scope.recent')}</Tab>
        </Tabs>

        {scope === 'ask' ? (
          <ChatPane>
            {chatTurns.length === 0 && !isThinking ? (
              <ChatEmpty>
                <ChatEmptyHint>{t('palette.ask.suggestionsTitle')}</ChatEmptyHint>
                <SuggestionsGrid>
                  {SUGGESTIONS_KEYS.map((k) => (
                    <SuggestionPill
                      key={k}
                      onClick={() => { void runAsk(t(k)); }}
                      type="button"
                    >
                      {t(k)}
                    </SuggestionPill>
                  ))}
                </SuggestionsGrid>
                <ChatEmptyHint style={{ marginTop: 4 }}>{t('palette.ask.hint')}</ChatEmptyHint>
              </ChatEmpty>
            ) : (
              <ChatTurns>
                {chatTurns.map((turn) => (
                  <React.Fragment key={turn.id}>
                    {/* User turn */}
                    <TurnBlock>
                      <TurnLabel>{t('palette.ask.you')}</TurnLabel>
                      <UserTurnText>{turn.question}</UserTurnText>
                    </TurnBlock>
                    {/* Assistant turn */}
                    <TurnBlock>
                      <TurnLabel>{t('palette.ask.atlantis')}</TurnLabel>
                      {turn.answer !== undefined ? (
                        <MarkdownBody>{turn.answer}</MarkdownBody>
                      ) : turn.error !== undefined ? (
                        <AskError>{turn.error}</AskError>
                      ) : (
                        <ThinkingDots aria-label={t('palette.ask.thinking')}>
                          <span /><span /><span />
                        </ThinkingDots>
                      )}
                    </TurnBlock>
                  </React.Fragment>
                ))}
                <div ref={chatEndRef} />
              </ChatTurns>
            )}
          </ChatPane>
        ) : (
          <ResultsList ref={listRef}>
            {selectableItems.length === 0 ? (
              <Empty>
                <div className="icon">
                  <Icon name="search" size={16} aria-hidden="true" />
                </div>
                <div className="title">
                  {t('palette.noMatch')}{' '}
                  {query && <span className="query">&ldquo;{query}&rdquo;</span>}
                </div>
                <div className="hint">{t('palette.emptyHint')}</div>
              </Empty>
            ) : (
              grouped.map((group, gi) => {
                if (group.kind === 'header') {
                  return (
                    <SectionHeader key={`h-${group.key}`}>
                      <SectionTitle>{group.label}</SectionTitle>
                      <SectionCount>{group.count}</SectionCount>
                    </SectionHeader>
                  );
                }
                counter += 1;
                const idx = counter;
                const selected = idx === selectedIndex;
                const item = group.item;
                return (
                  <Row
                    key={item.id + '-' + gi}
                    selected={selected}
                    data-selectable
                    onMouseEnter={() => setSelectedIndex(idx)}
                    onClick={() => item.onConfirm()}
                  >
                    {item.appIcon && (
                      <AppTile tintColor={item.appIcon.color} selected={selected}>
                        {item.appIcon.emoji}
                      </AppTile>
                    )}
                    {item.glyphIcon && (
                      <GlyphTile tintColor={item.glyphIcon.color}>
                        <Icon name={item.glyphIcon.iconName} size={18} aria-hidden="true" />
                      </GlyphTile>
                    )}
                    {item.gameGlyph && <GameTile>{item.gameGlyph}</GameTile>}
                    {item.kind === 'suggest' && (
                      <PlainGlyph>
                        <Icon name="sparkle" size={18} aria-hidden="true" />
                      </PlainGlyph>
                    )}
                    <RowText>
                      <RowLabel selected={selected}>{item.label}</RowLabel>
                      {item.meta && <RowMeta>{item.meta}</RowMeta>}
                    </RowText>
                    {item.shortcut && item.shortcut.length > 0 && (
                      <ShortcutChips>
                        {item.shortcut.map((k, i) => (
                          <Chip key={i}>{k}</Chip>
                        ))}
                      </ShortcutChips>
                    )}
                  </Row>
                );
              })
            )}
          </ResultsList>
        )}

        <Footer>
          {scope === 'ask' ? (
            <>
              <Hint><Chip>&crarr;</Chip>{t('palette.hint.ask')}</Hint>
              <Hint><Chip>esc</Chip>{t('palette.hint.close')}</Hint>
            </>
          ) : (
            <>
              <Hint><Chip>&uarr;</Chip><Chip>&darr;</Chip>{t('palette.hint.navigate')}</Hint>
              <Hint><Chip>&crarr;</Chip>{t('palette.hint.open')}</Hint>
              <Hint><Chip>esc</Chip>{t('palette.hint.close')}</Hint>
            </>
          )}
        </Footer>
      </Panel>
    </Backdrop>,
    document.body,
  );
}
